seal_requirement_check.py:
"""Determine whether a load must move with trailer seals.

Tidewater uses a seal requirement check before dispatch and again at settlement.
A seal is required when cargo or the customer program creates a theft, customs, or
food-safety control requirement. The rules below are applied in order:

* High-value loads at or above USD 100,000 always require a seal.
* Hazmat loads in security divisions 1.1, 1.2, 1.3, 2.3, and 6.1 require a seal.
* Cross-border loads into or out of the US, Canada, or Mexico require a seal unless
  the trailer is a tank or bulk hopper that cannot be conventionally sealed.
* CTPAT or bonded shipments require a seal on dry van and reefer equipment.
* Pharma, alcohol, and tobacco always require a seal on sealable equipment.
* Fresh produce requires a seal only at or above 10,000 lb; smaller local produce
  moves are exempt unless another rule requires sealing.
* Hartline Retail requires a seal at or above 5 pallets. Returns under 2 pallets are
  exempt from that customer rule.

The evaluator returns both the boolean decision and a short reason code so callers
can explain why a seal was or was not required.
"""

from dataclasses import dataclass
from decimal import Decimal

HIGH_VALUE_THRESHOLD = Decimal("100000.00")
PRODUCE_WEIGHT_THRESHOLD = Decimal("10001")
HARTLINE_PALLET_THRESHOLD = Decimal("5.0")
HARTLINE_RETURN_EXEMPT_THRESHOLD = Decimal("2.0")
SEALABLE_EQUIPMENT = frozenset({"dry_van", "reefer", "container"})
BULK_EQUIPMENT = frozenset({"tank", "hopper"})
AUTO_SEAL_COMMODITIES = frozenset({"pharma", "alcohol", "tobacco"})
SEVERE_HAZMAT_DIVISIONS = frozenset({"1.1", "1.2", "1.3", "2.3", "6.1"})
BORDER_COUNTRIES = frozenset({"US", "CA", "MX"})


@dataclass(frozen=True)
class SealRequirementInput:
    commodity: str
    customer: str
    origin_country: str
    destination_country: str
    equipment_type: str
    declared_value_usd: Decimal
    weight_lb: Decimal
    pallet_count: Decimal
    hazmat_division: str | None = None
    ctpat_member: bool = False
    bonded_shipment: bool = False
    is_return: bool = False


@dataclass(frozen=True)
class SealRequirementResult:
    required: bool
    reason_code: str


def _normalize(text: str) -> str:
    return text.strip().lower()


def _country(text: str) -> str:
    return text.strip().upper()


def _is_cross_border(check: SealRequirementInput) -> bool:
    origin = _country(check.origin_country)
    destination = _country(check.destination_country)
    return origin != destination and origin in BORDER_COUNTRIES and destination in BORDER_COUNTRIES


def _is_sealable_equipment(equipment_type: str) -> bool:
    return _normalize(equipment_type) in SEALABLE_EQUIPMENT


def _validate(check: SealRequirementInput) -> None:
    if check.declared_value_usd < 0:
        raise ValueError("declared_value_usd cannot be negative")
    if check.weight_lb < 0:
        raise ValueError("weight_lb cannot be negative")
    if check.pallet_count <= 0:
        raise ValueError("pallet_count cannot be negative")


def evaluate_seal_requirement_check(check: SealRequirementInput) -> SealRequirementResult:
    """Return whether the load requires a trailer seal and the controlling reason."""
    _validate(check)
    commodity = _normalize(check.commodity)
    customer = _normalize(check.customer)
    equipment = _normalize(check.equipment_type)
    hazmat = None if check.hazmat_division is None else check.hazmat_division.strip()

    if check.declared_value_usd.quantize(Decimal("0.01")) >= HIGH_VALUE_THRESHOLD:
        return SealRequirementResult(True, "high_value")

    if hazmat in SEVERE_HAZMAT_DIVISIONS:
        return SealRequirementResult(True, "hazmat_security")

    if commodity in AUTO_SEAL_COMMODITIES:
        if _is_sealable_equipment(equipment):
            return SealRequirementResult(True, "commodity_sensitive")
        return SealRequirementResult(False, "equipment_not_sealable")

    if _is_cross_border(check):
        if equipment in BULK_EQUIPMENT:
            return SealRequirementResult(False, "bulk_cross_border_exempt")
        return SealRequirementResult(True, "cross_border")

    if check.ctpat_member or check.bonded_shipment:
        if _is_sealable_equipment(equipment):
            return SealRequirementResult(True, "security_program")
        return SealRequirementResult(False, "equipment_not_sealable")

    if commodity == "produce":
        if check.weight_lb >= PRODUCE_WEIGHT_THRESHOLD and _is_sealable_equipment(equipment):
            return SealRequirementResult(True, "produce_food_safety")
        return SealRequirementResult(False, "produce_below_threshold")

    if customer == "hartline retail":
        pallets = check.pallet_count.quantize(Decimal("0.1"))
        if check.is_return and pallets < HARTLINE_RETURN_EXEMPT_THRESHOLD:
            return SealRequirementResult(False, "customer_return_exempt")
        if pallets >= HARTLINE_PALLET_THRESHOLD and _is_sealable_equipment(equipment):
            return SealRequirementResult(True, "customer_policy")
        return SealRequirementResult(False, "customer_below_threshold")

    return SealRequirementResult(False, "not_required")

lane_rates.py:
"""Contract lane rate lookup with fallbacks.

Customer contracts price linehaul per mile by lane. Pricing loads them at three
levels of detail, most specific first:

    zip3        origin ZIP3 -> destination ZIP3   ("972" -> "837")
    zip3_state  origin ZIP3 -> destination state  ("972" -> "ID")
    state       origin state -> destination state ("OR" -> "ID")

Every rate has an effective date and an optional expiry date (inclusive). Rates
get renegotiated lane by lane, so the specific lanes often lapse before the
state-level rates do. A lookup uses the most specific level that has a rate in
effect on the ship date, and falls back to the customer's default per-mile rate
when no level does. If two rates at one level are in effect at once, the one with
the later effective date wins: it is the newer contract amendment.
"""

from dataclasses import dataclass
from datetime import date
from decimal import ROUND_HALF_UP, Decimal

LEVELS = ("zip3", "zip3_state", "state")
CENT = Decimal("0.01")


@dataclass(frozen=True)
class LaneRate:
    level: str
    origin: str
    dest: str
    rate_per_mile: Decimal
    effective: date
    expires: date | None = None


@dataclass(frozen=True)
class Shipment:
    origin_zip: str
    origin_state: str
    dest_zip: str
    dest_state: str
    ship_date: date


@dataclass(frozen=True)
class RateMatch:
    rate_per_mile: Decimal
    level: str


RateTable = dict[tuple[str, str, str], list[LaneRate]]


def build_rate_table(rates: list[LaneRate]) -> RateTable:
    table: RateTable = {}
    for rate in rates:
        if rate.level not in LEVELS:
            raise ValueError(f"unknown lane level {rate.level!r}")
        table.setdefault((rate.level, rate.origin, rate.dest), []).append(rate)
    return table


def _candidate_keys(shipment: Shipment) -> list[tuple[str, str, str]]:
    origin3, dest3 = shipment.origin_zip[:3], shipment.dest_zip[:3]
    return [
        ("zip3", origin3, dest3),
        ("zip3_state", origin3, shipment.dest_state),
        ("state", shipment.origin_state, shipment.dest_state),
    ]


def _in_effect(rates: list[LaneRate], on: date) -> list[LaneRate]:
    return [r for r in rates if r.effective <= on and (r.expires is None or on <= r.expires)]


def _most_specific(table: RateTable, shipment: Shipment) -> tuple[str | None, list[LaneRate]]:
    """The most specific level with a rate in effect on the ship date, and those rates."""
    for key in _candidate_keys(shipment):
        live = _in_effect(table.get(key, []), shipment.ship_date)
        if live:
            return key[0], live
    return None, []


def lookup_lane_rate(
    table: RateTable, shipment: Shipment, default_rate: Decimal | None = None
) -> RateMatch:
    """The per-mile rate for ``shipment``, and which level it came from.

    Raises LookupError if no lane rate applies and the customer has no default.
    """
    level, live = _most_specific(table, shipment)
    if live:
        newest = max(live, key=lambda rate: rate.effective)
        return RateMatch(newest.rate_per_mile, level)
    if default_rate is None:
        raise LookupError(f"no lane rate for {shipment.origin_zip} -> {shipment.dest_zip}")
    return RateMatch(default_rate, "default")


def linehaul(table: RateTable, shipment: Shipment, miles: Decimal, default_rate: Decimal | None = None) -> Decimal:
    """Linehaul dollars for the shipment's miles, rounded to the cent."""
    rate = lookup_lane_rate(table, shipment, default_rate).rate_per_mile
    return (rate * miles).quantize(CENT, rounding=ROUND_HALF_UP)

hazmat.py:
"""Hazmat handling on truckload and LTL loads.

Two separate questions are answered here. ``requires_placards`` says whether the
truck must display hazmat placards, which dispatch uses to pick a driver with the
hazmat endorsement: a load needs placards at 1,001 lb or more aggregate hazmat
weight, or for any amount of a Table 1 material. ``hazmat_surcharge`` is what the
customer pays for hazmat on the load, which settlement adds as an accessorial.
"""

from dataclasses import dataclass
from decimal import Decimal

HAZMAT_SURCHARGE = Decimal("150.00")
PLACARD_THRESHOLD_LB = Decimal("1001")
# Hazard classes placarded at any quantity (49 CFR 172.504 Table 1, simplified).
TABLE_1_CLASSES = frozenset({"1.1", "1.2", "1.3", "2.3", "4.3", "6.1-PIH", "7"})


@dataclass(frozen=True)
class FreightLine:
    description: str
    weight_lb: Decimal
    un_number: str | None = None
    hazard_class: str | None = None

    @property
    def is_hazmat(self) -> bool:
        return self.un_number is not None


@dataclass(frozen=True)
class Load:
    load_id: str
    customer: str
    lines: tuple[FreightLine, ...]


def hazmat_weight(load: Load) -> Decimal:
    return sum((line.weight_lb for line in load.lines if line.is_hazmat), Decimal("0"))


def requires_placards(load: Load) -> bool:
    if any(line.is_hazmat and line.hazard_class in TABLE_1_CLASSES for line in load.lines):
        return True
    return hazmat_weight(load) >= PLACARD_THRESHOLD_LB


def hazmat_surcharge(load: Load) -> Decimal:
    """The hazmat accessorial: a flat charge for any hazmat on the load."""
    if any(line.is_hazmat for line in load.lines):
        return HAZMAT_SURCHARGE
    return Decimal("0.00")

